98	template <typename T>
99	__aicore__ inline void PrepareInvRmsTensorHelper(
100	    AscendC::LocalTensor<float> &dst,
101	    AscendC::LocalTensor<T> &out,
102	    AscendC::TBuf<AscendC::TPosition::VECCALC> &invRmsBuf)
103	{
104	    if constexpr (std::is_same_v<T, float>) {
105	        dst = out.template ReinterpretCast<float>();
106	    } else {
107	        dst = invRmsBuf.Get<float>();
108	    }
109	}
