// AscendC EmbeddingWithInitialLayernormBackward kernel
// Split along H dimension. Each core handles a contiguous H-chunk.
// Per-token: RMSNorm backward + scatter-add to embedding table.
// Supports bfloat16 grad_output/grad_embed_weight, fp32 hidden/rstd,
// norm_weight as fp32 or bf16.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t BLOCK_H = 256;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Kernel class
// =========================================================================

template <bool NEED_CAST_NORM>
class KernelEmbeddingWithInitLayernormBackward {
public:
    __aicore__ inline void Init(
        GM_ADDR grad_output, GM_ADDR input_ids, GM_ADDR hidden_states,
        GM_ADDR rstd, GM_ADDR norm_weight,
        GM_ADDR grad_embed_weight, GM_ADDR grad_norm_weight,
        int32_t total_tokens, int32_t vocab_size, int32_t hidden_size,
        int32_t block_h, int32_t h_num, int32_t used_core_num,
        int32_t tasks_per_core)
    {
        total_tokens_ = total_tokens;
        hidden_size_ = hidden_size;
        block_h_ = block_h;
        h_num_ = h_num;
        used_core_num_ = used_core_num;
        tasks_per_core_ = tasks_per_core;

        gradOutputGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ bfloat16_t *>(grad_output),
            static_cast<uint64_t>(total_tokens) * hidden_size);
        inputIdsGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t *>(input_ids), total_tokens);
        hiddenGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ float *>(hidden_states),
            static_cast<uint64_t>(total_tokens) * hidden_size);
        rstdGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ float *>(rstd), total_tokens);
        normWeightGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ float *>(norm_weight), hidden_size);
        gradEmbedGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ bfloat16_t *>(grad_embed_weight),
            static_cast<uint64_t>(vocab_size) * hidden_size);
        gradNormGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ bfloat16_t *>(grad_norm_weight), hidden_size);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        // Input queues
        pipe_.InitBuffer(gradInQueue_, BUFFER_NUM, static_cast<uint32_t>(BLOCK_H) * sizeof(bfloat16_t));
        pipe_.InitBuffer(hiddenInQueue_, BUFFER_NUM, static_cast<uint32_t>(BLOCK_H) * sizeof(float));
        pipe_.InitBuffer(scatterReadQueue_, BUFFER_NUM, static_cast<uint32_t>(BLOCK_H) * sizeof(bfloat16_t));
        // Output queues
        pipe_.InitBuffer(scatterWriteQueue_, BUFFER_NUM, static_cast<uint32_t>(BLOCK_H) * sizeof(bfloat16_t));
        pipe_.InitBuffer(normOutQueue_, BUFFER_NUM, static_cast<uint32_t>(BLOCK_H) * sizeof(bfloat16_t));
        // Compute buffers (fp32)
        pipe_.InitBuffer(normWeightBuf_, static_cast<uint32_t>(BLOCK_H) * sizeof(float));
        pipe_.InitBuffer(normWeightAccBuf_, static_cast<uint32_t>(BLOCK_H) * sizeof(float));
        pipe_.InitBuffer(gradCastBuf_, static_cast<uint32_t>(BLOCK_H) * sizeof(float));
        pipe_.InitBuffer(tempBuf_, static_cast<uint32_t>(BLOCK_H) * sizeof(float));
        pipe_.InitBuffer(gradHiddenBuf_, static_cast<uint32_t>(BLOCK_H) * sizeof(float));
        pipe_.InitBuffer(scatterCastInBuf_, static_cast<uint32_t>(BLOCK_H) * sizeof(float));
        pipe_.InitBuffer(scatterCastOutBuf_, static_cast<uint32_t>(BLOCK_H) * sizeof(float));
        // Norm weight cast (only if bf16 norm_weight)
        if constexpr (NEED_CAST_NORM) {
            pipe_.InitBuffer(normWeightInBuf_, static_cast<uint32_t>(BLOCK_H) * sizeof(float));
            pipe_.InitBuffer(normWeightCastBuf_, static_cast<uint32_t>(BLOCK_H) * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int core_idx = AscendC::GetBlockIdx();
            for (int32_t local_idx = 0; local_idx < tasks_per_core_; ++local_idx) {
                int32_t bx = core_idx * tasks_per_core_ + local_idx;
                if (bx >= h_num_) {
                    continue;
                }
                int32_t h_start = bx * block_h_;
                int32_t h_chunk = (h_start + block_h_ <= hidden_size_) ? block_h_ : (hidden_size_ - h_start);
                ProcessHChunk(h_start, h_chunk);
            }
        }
    }

private:
    // -----------------------------------------------------------------------
    // Per-H-chunk processing
    // -----------------------------------------------------------------------

    __aicore__ inline void ProcessHChunk(int32_t h_start, int32_t h_chunk)
    {
        // Load norm_weight chunk
        LoadNormWeight(h_start, h_chunk);

        // Initialize accumulator
        normWeightAccLocal_ = normWeightAccBuf_.Get<float>();
        AscendC::Duplicate(normWeightAccLocal_, 0.0f, h_chunk);

        // Process all tokens
        for (int32_t token = 0; token < total_tokens_; ++token) {
            ProcessToken(token, h_start, h_chunk);
        }

        // Write norm_weight gradient to output
        CopyOutNormWeight(h_start, h_chunk);
    }

    // -----------------------------------------------------------------------
    // Norm weight loading
    // -----------------------------------------------------------------------

    __aicore__ inline void LoadNormWeight(int32_t h_start, int32_t h_chunk)
    {
        if constexpr (NEED_CAST_NORM) {
            // norm_weight is stored as float in GM (it was cast from bf16 by host)
            // Actually host passes original dtype. Let me handle both cases.
            // norm_weight in GM is float (fp32 format) — host passes it as float*.
            // But if norm_weight was originally bf16, the host casts to fp32.
            // For simplicity, we always receive float* for norm_weight.
