// AscendC EmbeddingWithInitialLayernormBackward kernel
// Split along H dimension into block_h=256 chunks per core.
// Each core processes all B*S tokens for its H-chunk:
//   For each token: load tile, compute RMSNorm backward, scatter-add to embedding table.
// Accumulate: grad_norm_weight[H] in fp32, output as bf16.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t BLOCK_H = 256;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline void LoadGmToUbBf16(
    AscendC::LocalTensor<bfloat16_t> &dst,
    AscendC::GlobalTensor<bfloat16_t> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * sizeof(bfloat16_t), 0, 0, 0};
    AscendC::DataCopyPadExtParams<bfloat16_t> padParams{true, 0, 0, static_cast<bfloat16_t>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

__aicore__ inline void LoadGmToUbFp32(
    AscendC::LocalTensor<float> &dst,
    AscendC::GlobalTensor<float> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * sizeof(float), 0, 0, 0};
    AscendC::DataCopyPadExtParams<float> padParams{true, 0, 0, 0.0f};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

__aicore__ inline void StoreUbToGmBf16(
    AscendC::GlobalTensor<bfloat16_t> dst,
    AscendC::LocalTensor<bfloat16_t> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * sizeof(bfloat16_t), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Kernel class
// =========================================================================

class KernelEmbeddingWithInitLayernormBackward {
public:
    __aicore__ inline void Init(
        GM_ADDR grad_output, GM_ADDR input_ids, GM_ADDR hidden_states,
        GM_ADDR rstd, GM_ADDR norm_weight,
        GM_ADDR grad_embed_weight, GM_ADDR grad_norm_weight,
        int32_t total_tokens, int32_t hidden_size,
        int32_t block_h, int32_t h_num, int32_t used_core_num,
        int32_t tasks_per_core)
    {
        total_tokens_ = total_tokens;
        hidden_size_ = hidden_size;
        block_h_ = block_h;
        h_num_ = h_num;
        used_core_num_ = used_core_num;
        tasks_per_core_ = tasks_per_core;

        // Set global buffers
        // All inputs/outputs use consistent dtypes:
        // - grad_output: bf16
        // - input_ids: int32
        // - hidden_states: fp32
        // - rstd: fp32  (stored as [total_tokens, 1] in GM, but accessed as 1D linear)
        // - norm_weight: fp32 (host/wrapper casts bf16→fp32 if needed)
        // - grad_embed_weight: bf16
        // - grad_norm_weight: bf16
        gradOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bfloat16_t *>(grad_output),
            static_cast<uint64_t>(total_tokens_) * hidden_size_);
        inputIdsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(input_ids), total_tokens_);
        hiddenGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(hidden_states),
            static_cast<uint64_t>(total_tokens_) * hidden_size_);
        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(rstd), total_tokens_);
        normWeightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(norm_weight), hidden_size_);
        gradEmbedGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bfloat16_t *>(grad_embed_weight),
            static_cast<uint64_t>(0xFFFFFFFF));  // vocab_size can be large, use max
        gradNormGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bfloat16_t *>(grad_norm_weight), hidden_size_);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        // Input queues: one slot each (per-token serial processing)
        pipe_.InitBuffer(gradInQueue_, BUFFER_NUM, BLOCK_H * sizeof(bfloat16_t));
        pipe_.InitBuffer(hiddenInQueue_, BUFFER_NUM, BLOCK_H * sizeof(float));
        pipe_.InitBuffer(scatterReadQueue_, BUFFER_NUM, BLOCK_H * sizeof(bfloat16_t));
        // Output queues
        pipe_.InitBuffer(scatterWriteQueue_, BUFFER_NUM, BLOCK_H * sizeof(bfloat16_t));
        pipe_.InitBuffer(normOutQueue_, BUFFER_NUM, BLOCK_H * sizeof(bfloat16_t));
        // FP32 compute buffers
        pipe_.InitBuffer(normWeightBuf_, BLOCK_H * sizeof(float));
        pipe_.InitBuffer(normAccBuf_, BLOCK_H * sizeof(float));
        pipe_.InitBuffer(gradCastBuf_, BLOCK_H * sizeof(float));
        pipe_.InitBuffer(tempBuf_, BLOCK_H * sizeof(float));
        pipe_.InitBuffer(gradHiddenBuf_, BLOCK_H * sizeof(float));
        pipe_.InitBuffer(scatterCastInBuf_, BLOCK_H * sizeof(float));
        pipe_.InitBuffer(scatterCastOutBuf_, BLOCK_H * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int core_idx = AscendC::GetBlockIdx();
            for (int32_t local_idx = 0; local_idx < tasks_per_core_; ++local_idx) {
                int32_t bx = core_idx * tasks_per_core_ + local_idx;
                if (bx >= h_num_) { continue; }

                int32_t h_start = bx * block_h_;
                int32_t h_chunk = (h_start + block_h_ <= hidden_size_) ? block_h_ : (hidden_size_ - h_start);

                ProcessHChunk(h_start, h_chunk);
            }
        }
    }

private:
    // -----------------------------------------------------------------------
    // Process one H-chunk: norm_weight load → token loop → norm_weight write
    // -----------------------------------------------------------------------

    __aicore__ inline void ProcessHChunk(int32_t h_start, int32_t h_chunk)
    {
        // 1. Load norm_weight[h_start:h_start+h_chunk] (fp32)
        LoadNormWeight(h_start, h_chunk);

        // 2. Zero-initialize grad_norm_weight accumulator
        normAccLocal_ = normAccBuf_.Get<float>();
        AscendC::Duplicate(normAccLocal_, 0.0f, h_chunk);

        // 3. Process all tokens
        for (int32_t t = 0; t < total_tokens_; ++t) {
            ProcessToken(t, h_start, h_chunk);
        }

        // 4. Write grad_norm_weight accumulator to output (fp32→bf16)
        CopyOutNormWeight(h_start, h_chunk);
    }

    // -----------------------------------------------------------------------
    // Norm weight loading
    // -----------------------------------------------------------------------

    __aicore__ inline void LoadNormWeight(int32_t h_start, int32_t h_chunk)
    {
        normWeightLocal_ = normWeightBuf_.Get<float>();
        LoadGmToUbFp32(normWeightLocal_, normWeightGM_[h_start], static_cast<uint32_t>(h_chunk));
    }

    // -----------------------------------------------------------------------
    // Norm weight output
    // -----------------------------------------------------------------------

    __aicore__ inline void CopyOutNormWeight(int32_t h_start, int32_t h_chunk)
    {
        normOutLocal_ = normOutQueue_.AllocTensor<bfloat16_t>();
        // Cast fp32 accumulator → bf16
        AscendC::Cast(normOutLocal_, normAccLocal_, AscendC::RoundMode::CAST_ROUND, h_chunk);
        AscendC::PipeBarrier<PIPE_V>();
        normOutQueue_.EnQue(normOutLocal_);

        normOutLocal_ = normOutQueue_.DeQue<bfloat16_t>();
        StoreUbToGmBf16(gradNormGM_[h_start], normOutLocal_, static_cast<uint32_t>(h_chunk));
        normOutQueue_.FreeTensor(normOutLocal_);
    }

    // -----------------------------------------------------------------------
    // Per-token processing
    // -----------------------------------------------------------------------

    __aicore__ inline void ProcessToken(int32_t t, int32_t h_start, int32_t h_chunk)
    {
        // Step 1: Load grad_output[t, h_start:h_chunk] (bf16)
        CopyInGradOutput(t, h_start, h_chunk);

        // Step 2: Load hidden_states[t, h_start:h_chunk] (fp32)
        CopyInHidden(t, h_start, h_chunk);

        // Step 3: Load rstd[t] (fp32 scalar)
        float rstd_val = rstdGM_.GetValue(t);

        // Compute: temp = grad_output_fp32 * hidden * rstd
        //         grad_hidden = grad_output_fp32 * norm_weight * rstd
        ComputeRMSNormBackward(h_chunk, rstd_val);

        // Step 4: Load input_ids[t] (int32)
        int32_t vocab_idx = inputIdsGM_.GetValue(t);

        // Step 5: Scatter-add: read grad_embed_weight[vocab_idx, h_start:h_chunk],
        //         add grad_hidden, write back
        ScatterAdd(vocab_idx, h_start, h_chunk);
    }

    // -----------------------------------------------------------------------
    // CopyIn: grad_output chunk (bf16 → cast → fp32)
    // -----------------------------------------------------------------------

    __aicore__ inline void CopyInGradOutput(int32_t t, int32_t h_start, int32_t h_chunk)
    {
        gradInLocal_ = gradInQueue_.AllocTensor<bfloat16_t>();
        LoadGmToUbBf16(gradInLocal_,
            gradOutGM_[static_cast<uint64_t>(t) * hidden_size_ + h_start],
            static_cast<uint32_t>(h_chunk));
        gradInQueue_.EnQue(gradInLocal_);
    }

    // -----------------------------------------------------------------------
    // CopyIn: hidden_states chunk (fp32)
    // -----------------------------------------------------------------------

    __aicore__ inline void CopyInHidden(int32_t t, int32_t h_start, int32_t h_chunk)
    {
        hiddenInLocal_ = hiddenInQueue_.AllocTensor<float>();
        LoadGmToUbFp32(hiddenInLocal_,
            hiddenGM_[static_cast<uint64_t>(t) * hidden_size_ + h_start],
            static_cast<uint32_t>(h_chunk));
        hiddenInQueue_.EnQue(hiddenInLocal_);
    }

    // -----------------------------------------------------------------------
    // Compute: RMSNorm backward for one token
    // -----------------------------------------------------------------------

    __aicore__ inline void ComputeRMSNormBackward(int32_t h_chunk, float rstd_val)
    {
        // DeQue grad_output
        gradInLocal_ = gradInQueue_.DeQue<bfloat16_t>();
        gradCastLocal_ = gradCastBuf_.Get<float>();
        AscendC::Cast(gradCastLocal_, gradInLocal_, AscendC::RoundMode::CAST_NONE, h_chunk);
        AscendC::PipeBarrier<PIPE_V>();
        gradInQueue_.FreeTensor(gradInLocal_);

        // DeQue hidden_states
        hiddenInLocal_ = hiddenInQueue_.DeQue<float>();
        float *hiddenFp32 = reinterpret_cast<float *>(hiddenInLocal_.GetPhyAddr());
        AscendC::LocalTensor<float> hiddenLocal(hiddenFp32, hiddenInLocal_.GetShape());
        (void)hiddenLocal;

        // temp = grad_output_fp32 * hidden_fp32
        tempLocal_ = tempBuf_.Get<float>();
        AscendC::Mul(tempLocal_, gradCastLocal_, hiddenInLocal_, h_chunk);

        // temp *= rstd
        AscendC::Muls(tempLocal_, tempLocal_, rstd_val, h_chunk);

        // grad_norm_weight_acc += temp
        AscendC::Add(normAccLocal_, normAccLocal_, tempLocal_, h_chunk);

        // grad_hidden = grad_output_fp32 * norm_weight_fp32
        gradHiddenLocal_ = gradHiddenBuf_.Get<float>();
        AscendC::Mul(gradHiddenLocal_, gradCastLocal_, normWeightLocal_, h_chunk);

        // grad_hidden *= rstd
        AscendC::Muls(gradHiddenLocal_, gradHiddenLocal_, rstd_val, h_chunk);

        hiddenInQueue_.FreeTensor(hiddenInLocal_);
    }

    // -----------------------------------------------------------------------
    // Scatter-add: read → add → write embedding row chunk
    // -----------------------------------------------------------------------

    __aicore__ inline void ScatterAdd(int32_t vocab_idx, int32_t h_start, int32_t h_chunk)
    {
        // Read current grad_embed_weight[vocab_idx, h_start:h_chunk] (bf16)
        scatterReadLocal_ = scatterReadQueue_.AllocTensor<bfloat16_t>();
        LoadGmToUbBf16(scatterReadLocal_,
            gradEmbedGM_[static_cast<uint64_t>(vocab_idx) * hidden_size_ + h_start],
            static_cast<uint32_t>(h_chunk));
        scatterReadQueue_.EnQue(scatterReadLocal_);

        // DeQue, cast to fp32
        scatterReadLocal_ = scatterReadQueue_.DeQue<bfloat16_t>();
        scatterCastInLocal_ = scatterCastInBuf_.Get<float>();
        AscendC::Cast(scatterCastInLocal_, scatterReadLocal_, AscendC::RoundMode::CAST_NONE, h_chunk);
        AscendC::PipeBarrier<PIPE_V>();
        scatterReadQueue_.FreeTensor(scatterReadLocal_);

        // Add grad_hidden
        AscendC::Add(scatterCastInLocal_, scatterCastInLocal_, gradHiddenLocal_, h_chunk);

        // Cast to bf16 and enqueue for write-back
        scatterWriteLocal_ = scatterWriteQueue_.AllocTensor<bfloat16_t>();
        AscendC::Cast(scatterWriteLocal_, scatterCastInLocal_, AscendC::RoundMode::CAST_ROUND, h_chunk);
        AscendC::PipeBarrier<PIPE_V>();
        scatterWriteQueue_.EnQue(scatterWriteLocal_);

        // DeQue and write to GM
        scatterWriteLocal_ = scatterWriteQueue_.DeQue<bfloat16_t>();
        StoreUbToGmBf16(
            gradEmbedGM_[static_cast<uint64_t>(vocab_idx) * hidden_size_ + h_start],
            scatterWriteLocal_,
            static_cast<uint32_t>(h_chunk));
        scatterWriteQueue_.FreeTensor(scatterWriteLocal_);
    }

private:
    int32_t total_tokens_ = 0;
    int32_t hidden_size_ = 0;
    int32_t block_h_ = 0;
    int32_t h_num_ = 0;
    int32_t used_core_num_ = 0;
    int32_t tasks_per_core_ = 0;

    AscendC::TPipe pipe_;

    // Global tensors
    AscendC::GlobalTensor<bfloat16_t> gradOutGM_;
    AscendC::GlobalTensor<int32_t> inputIdsGM_;
    AscendC::GlobalTensor<float> hiddenGM_;
    AscendC::GlobalTensor<float> rstdGM_;
    AscendC::GlobalTensor<float> normWeightGM_;
    AscendC::GlobalTensor<bfloat16_t> gradEmbedGM_;
    AscendC::GlobalTensor<bfloat16_t> gradNormGM_;

    // Queues (VECIN / VECOUT)
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gradInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hiddenInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> scatterReadQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> scatterWriteQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> normOutQueue_;

    // FP32 compute buffers (TBuf)
    AscendC::TBuf<AscendC::TPosition::VECCALC> normWeightBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> normAccBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gradCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gradHiddenBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scatterCastInBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scatterCastOutBuf_;

    // Local tensor handles
    AscendC::LocalTensor<bfloat16_t> gradInLocal_;
    AscendC::LocalTensor<float> hiddenInLocal_;
    AscendC::LocalTensor<bfloat16_t> scatterReadLocal_;
    AscendC::LocalTensor<bfloat16_t> scatterWriteLocal_;
    AscendC::LocalTensor<bfloat16_t> normOutLocal_;
    AscendC::LocalTensor<float> normWeightLocal_;
    AscendC::LocalTensor<float> normAccLocal_;
    AscendC::LocalTensor<float> gradCastLocal_;
    AscendC::LocalTensor<float> tempLocal_;
    AscendC::LocalTensor<float> gradHiddenLocal_;
    AscendC::LocalTensor<float> scatterCastInLocal_;
    AscendC::LocalTensor<float> scatterCastOutLocal_;
};

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void embedding_with_init_layernorm_backward(
    GM_ADDR grad_output, GM_ADDR input_ids, GM_ADDR hidden_states,
    GM_ADDR rstd, GM_ADDR norm_weight,
    GM_ADDR grad_embed_weight, GM_ADDR grad_norm_weight,
    int32_t total_tokens, int32_t hidden_size,
    int32_t block_h, int32_t h_num, int32_t used_core_num,
    int32_t tasks_per_core)
{
    KernelEmbeddingWithInitLayernormBackward kernel;
    kernel.Init(grad_output, input_ids, hidden_states, rstd, norm_weight,
                grad_embed_weight, grad_norm_weight,
                total_tokens, hidden_size,
                block_h, h_num, used_core_num, tasks_per_core);
    kernel.Process();
}
