// EmbeddingWithInitialLayernormBackward op_host
// Tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_embedding_with_init_layernorm_backward.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_H = 256;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

std::vector<at::Tensor> embedding_with_init_layernorm_backward(
    const at::Tensor &grad_output,
    const at::Tensor &input_ids,
    const at::Tensor &hidden_states_fp32,
    const at::Tensor &rstd,
    const at::Tensor &norm_weight)
{
    // Input validation
    TORCH_CHECK(grad_output.dim() == 2, "grad_output must be [total_tokens, H]");
    TORCH_CHECK(input_ids.dim() == 1, "input_ids must be [total_tokens]");
    TORCH_CHECK(hidden_states_fp32.dim() == 2, "hidden_states must be [total_tokens, H]");
    TORCH_CHECK(rstd.dim() == 2 && rstd.sizes()[1] == 1, "rstd must be [total_tokens, 1]");
    TORCH_CHECK(norm_weight.dim() == 1, "norm_weight must be [H]");

    int32_t total_tokens = static_cast<int32_t>(grad_output.sizes()[0]);
    int32_t hidden_size = static_cast<int32_t>(grad_output.sizes()[1]);
    int32_t vocab_size = 65536;  // from model.py

    TORCH_CHECK(grad_output.scalar_type() == at::kBFloat16,
        "grad_output must be bfloat16");
    TORCH_CHECK(hidden_states_fp32.scalar_type() == at::kFloat,
        "hidden_states_fp32 must be float32");
    TORCH_CHECK(rstd.scalar_type() == at::kFloat,
        "rstd must be float32");

    // norm_weight: accept fp32 or bf16; cast bf16→fp32 in host if needed
    at::Tensor norm_weight_fp32;
    if (norm_weight.scalar_type() == at::kBFloat16) {
        norm_weight_fp32 = norm_weight.to(at::kFloat).contiguous();
    } else if (norm_weight.scalar_type() == at::kFloat) {
        norm_weight_fp32 = norm_weight.contiguous();
    } else {
        TORCH_CHECK(false, "norm_weight must be float32 or bfloat16");
    }

    // input_ids: accept int64 or int32; cast int64→int32 in host if needed
    at::Tensor input_ids_int32;
    if (input_ids.scalar_type() == at::kLong) {
        input_ids_int32 = input_ids.to(at::kInt).contiguous();
    } else if (input_ids.scalar_type() == at::kInt) {
        input_ids_int32 = input_ids.contiguous();
    } else {
        TORCH_CHECK(false, "input_ids must be int64 or int32");
    }

    // Ensure contiguous inputs
    at::Tensor grad_output_contig = grad_output.contiguous();
    at::Tensor hidden_contig = hidden_states_fp32.contiguous();
    at::Tensor rstd_contig = rstd.contiguous();

    // Tiling computation
    int32_t block_h = DEFAULT_BLOCK_H;
    int32_t h_num = (hidden_size + block_h - 1) / block_h;
    int32_t used_core_num = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, h_num));
    int32_t tasks_per_core = (h_num + used_core_num - 1) / used_core_num;

    // Allocate output tensors
    at::Tensor grad_embed_weight = at::zeros(
        {vocab_size, hidden_size},
        grad_output.options().dtype(at::kBFloat16));
    at::Tensor grad_norm_weight = at::zeros(
        {hidden_size},
        grad_output.options().dtype(at::kBFloat16));

    // All params as left values (required by EXEC_KERNEL_CMD)
    uint32_t block_dim = static_cast<uint32_t>(used_core_num);

    EXEC_KERNEL_CMD(embedding_with_init_layernorm_backward, block_dim,
                    grad_output_contig, input_ids_int32, hidden_contig,
                    rstd_contig, norm_weight_fp32,
                    grad_embed_weight, grad_norm_weight,
                    total_tokens, hidden_size,
                    block_h, h_num, used_core_num, tasks_per_core);

    return {grad_embed_weight, grad_norm_weight};
}

}  // namespace ascend_kernel
