// AscendC EmbeddingWithInitialLayernormBackward kernel
// Split along H dimension into block_h=256 chunks per core.
// grad_embed_weight: fp32 internal for precision (host casts to bf16 after kernel returns).
// grad_norm_weight: accumulated fp32, output bf16.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t BLOCK_H = 256;

__aicore__ inline void LoadGmToUbBf16(
    AscendC::LocalTensor<bfloat16_t> &dst,
    AscendC::GlobalTensor<bfloat16_t> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(count * sizeof(bfloat16_t)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<bfloat16_t> pp{true, 0, 0, static_cast<bfloat16_t>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

__aicore__ inline void LoadGmToUbFp32(
    AscendC::LocalTensor<float> &dst,
    AscendC::GlobalTensor<float> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(count * sizeof(float)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<float> pp{true, 0, 0, 0.0f};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

__aicore__ inline void StoreUbToGmFp32(
    AscendC::GlobalTensor<float> dst,
    AscendC::LocalTensor<float> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(count * sizeof(float)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

__aicore__ inline void StoreUbToGmBf16(
    AscendC::GlobalTensor<bfloat16_t> dst,
    AscendC::LocalTensor<bfloat16_t> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(count * sizeof(bfloat16_t)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

class KernelEmbeddingWithInitLayernormBackward {
public:
    __aicore__ inline void Init(
        GM_ADDR go, GM_ADDR ids, GM_ADDR hs,
        GM_ADDR rstd, GM_ADDR nw,
        GM_ADDR gew, GM_ADDR gnw,
        int32_t tt, int32_t vs, int32_t hs_sz,
        int32_t bh, int32_t hn, int32_t ucn, int32_t tpc)
    {
        total_tokens_ = tt;
        hidden_size_ = hs_sz;
        block_h_ = bh;
        h_num_ = hn;
        used_core_num_ = ucn;
        tasks_per_core_ = tpc;

        gradOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bfloat16_t *>(go),
            static_cast<uint64_t>(tt) * hs_sz);
        inputIdsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(ids), tt);
        hiddenGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(hs),
            static_cast<uint64_t>(tt) * hs_sz);
        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(rstd), tt);
        normWeightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(nw), hs_sz);
        gradEmbedGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(gew),
            static_cast<uint64_t>(vs) * hs_sz);
        gradNormGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bfloat16_t *>(gnw), hs_sz);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        uint32_t bh = static_cast<uint32_t>(BLOCK_H);
        pipe_.InitBuffer(gradInQ_, BUFFER_NUM, bh * sizeof(bfloat16_t));
        pipe_.InitBuffer(hiddenInQ_, BUFFER_NUM, bh * sizeof(float));
        pipe_.InitBuffer(embedInQ_, BUFFER_NUM, bh * sizeof(float));
        pipe_.InitBuffer(embedOutQ_, BUFFER_NUM, bh * sizeof(float));
        pipe_.InitBuffer(normOutQ_, BUFFER_NUM, bh * sizeof(bfloat16_t));
        pipe_.InitBuffer(nwBuf_, bh * sizeof(float));
        pipe_.InitBuffer(normAccBuf_, bh * sizeof(float));
        pipe_.InitBuffer(gradCastBuf_, bh * sizeof(float));
        pipe_.InitBuffer(tmpBuf_, bh * sizeof(float));
        pipe_.InitBuffer(ghBuf_, bh * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int ci = AscendC::GetBlockIdx();
            for (int32_t li = 0; li < tasks_per_core_; ++li) {
                int32_t bx = ci * tasks_per_core_ + li;
                if (bx >= h_num_) continue;
                int32_t hs = bx * block_h_;
                int32_t hc = (hs + block_h_ <= hidden_size_) ? block_h_ : (hidden_size_ - hs);
                ProcessHChunk(hs, hc);
            }
        }
    }

private:
    __aicore__ inline void ProcessHChunk(int32_t hs, int32_t hc)
    {
        nwLocal_ = nwBuf_.Get<float>();
        LoadGmToUbFp32(nwLocal_, normWeightGM_[hs], static_cast<uint32_t>(hc));
        AscendC::PipeBarrier<PIPE_MTE2>();

        normAccLocal_ = normAccBuf_.Get<float>();
        AscendC::Duplicate(normAccLocal_, 0.0f, hc);

        for (int32_t t = 0; t < total_tokens_; ++t) {
            ProcessToken(t, hs, hc);
        }

        // Write grad_norm_weight (fp32→bf16)
        normOutLocal_ = normOutQ_.AllocTensor<bfloat16_t>();
        AscendC::Cast(normOutLocal_, normAccLocal_, AscendC::RoundMode::CAST_ROUND, hc);
        AscendC::PipeBarrier<PIPE_V>();
        normOutQ_.EnQue(normOutLocal_);
        normOutLocal_ = normOutQ_.DeQue<bfloat16_t>();
        StoreUbToGmBf16(gradNormGM_[hs], normOutLocal_, static_cast<uint32_t>(hc));
        normOutQ_.FreeTensor(normOutLocal_);
    }

    __aicore__ inline void ProcessToken(int32_t t, int32_t hs, int32_t hc)
    {
        // CopyIn: grad_output[t, hs:hc] (bf16)
        gradInLocal_ = gradInQ_.AllocTensor<bfloat16_t>();
        LoadGmToUbBf16(gradInLocal_,
            gradOutGM_[static_cast<uint64_t>(t) * hidden_size_ + hs],
            static_cast<uint32_t>(hc));
        gradInQ_.EnQue(gradInLocal_);

        // CopyIn: hidden[t, hs:hc] (fp32)
        hiddenInLocal_ = hiddenInQ_.AllocTensor<float>();
        LoadGmToUbFp32(hiddenInLocal_,
            hiddenGM_[static_cast<uint64_t>(t) * hidden_size_ + hs],
            static_cast<uint32_t>(hc));
        hiddenInQ_.EnQue(hiddenInLocal_);

        // CopyIn: embed[input_ids[t], hs:hc] (fp32)
        int32_t vi = inputIdsGM_.GetValue(t);
        embedInLocal_ = embedInQ_.AllocTensor<float>();
        LoadGmToUbFp32(embedInLocal_,
            gradEmbedGM_[static_cast<uint64_t>(vi) * hidden_size_ + hs],
            static_cast<uint32_t>(hc));
        embedInQ_.EnQue(embedInLocal_);

        // Compute
        float rv = rstdGM_.GetValue(t);
        Compute(hs, hc, rv, vi);
    }

    __aicore__ inline void Compute(int32_t hs, int32_t hc, float rv, int32_t vi)
    {
        // DeQue grad_output, cast bf16→fp32
        gradInLocal_ = gradInQ_.DeQue<bfloat16_t>();
        gradCastLocal_ = gradCastBuf_.Get<float>();
        AscendC::Cast(gradCastLocal_, gradInLocal_, AscendC::RoundMode::CAST_NONE, hc);
        AscendC::PipeBarrier<PIPE_V>();
        gradInQ_.FreeTensor(gradInLocal_);

        // DeQue hidden (fp32)
        hiddenInLocal_ = hiddenInQ_.DeQue<float>();

        // temp = grad_fp32 * hidden * rstd
        tmpLocal_ = tmpBuf_.Get<float>();
        AscendC::Mul(tmpLocal_, gradCastLocal_, hiddenInLocal_, hc);
        AscendC::Muls(tmpLocal_, tmpLocal_, rv, hc);

        // norm_acc += temp
        AscendC::Add(normAccLocal_, normAccLocal_, tmpLocal_, hc);

        // grad_hidden = grad_fp32 * norm_weight * rstd
        ghLocal_ = ghBuf_.Get<float>();
        AscendC::Mul(ghLocal_, gradCastLocal_, nwLocal_, hc);
        AscendC::Muls(ghLocal_, ghLocal_, rv, hc);

        hiddenInQ_.FreeTensor(hiddenInLocal_);

        // DeQue embed row, add grad_hidden, write back
        embedInLocal_ = embedInQ_.DeQue<float>();
        AscendC::Add(embedInLocal_, embedInLocal_, ghLocal_, hc);

        // Write to embedOutQ
        embedOutLocal_ = embedOutQ_.AllocTensor<float>();
        AscendC::DataCopy(embedOutLocal_, embedInLocal_, hc);
        embedOutQ_.EnQue(embedOutLocal_);

        embedOutLocal_ = embedOutQ_.DeQue<float>();
        StoreUbToGmFp32(
            gradEmbedGM_[static_cast<uint64_t>(vi) * hidden_size_ + hs],
            embedOutLocal_,
            static_cast<uint32_t>(hc));
        embedOutQ_.FreeTensor(embedOutLocal_);
        embedInQ_.FreeTensor(embedInLocal_);
    }

private:
    int32_t total_tokens_ = 0, hidden_size_ = 0, block_h_ = 0;
    int32_t h_num_ = 0, used_core_num_ = 0, tasks_per_core_ = 0;
    AscendC::TPipe pipe_;

    AscendC::GlobalTensor<bfloat16_t> gradOutGM_;
    AscendC::GlobalTensor<int32_t> inputIdsGM_;
    AscendC::GlobalTensor<float> hiddenGM_, rstdGM_, normWeightGM_;
    AscendC::GlobalTensor<float> gradEmbedGM_;
    AscendC::GlobalTensor<bfloat16_t> gradNormGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gradInQ_, hiddenInQ_, embedInQ_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> embedOutQ_, normOutQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> nwBuf_, normAccBuf_, gradCastBuf_, tmpBuf_, ghBuf_;

    AscendC::LocalTensor<bfloat16_t> gradInLocal_, normOutLocal_;
    AscendC::LocalTensor<float> hiddenInLocal_, embedInLocal_, embedOutLocal_;
    AscendC::LocalTensor<float> nwLocal_, normAccLocal_, gradCastLocal_, tmpLocal_, ghLocal_;
};

extern "C" __global__ __aicore__ void embedding_with_init_layernorm_backward(
    GM_ADDR go, GM_ADDR ids, GM_ADDR hs,
    GM_ADDR rstd, GM_ADDR nw,
    GM_ADDR gew, GM_ADDR gnw,
    int32_t tt, int32_t vs, int32_t hs_sz,
    int32_t bh, int32_t hn, int32_t ucn, int32_t tpc)
{
    KernelEmbeddingWithInitLayernormBackward k;
    k.Init(go, ids, hs, rstd, nw, gew, gnw, tt, vs, hs_sz, bh, hn, ucn, tpc);
    k.Process();
}
